from qiskit import QuantumCircuit

qc = QuantumCircuit(5)

# Apply Hadamard gates to all qubits
for q in range(5):
    qc.h(q)

# Apply CPhase (Controlled Phase) gates between pairs of qubits with the correct angle
angles = [2 * 3.14159 / (2 ** i) for i in range(1, 6)]
for i in range(4):
    for j in range(i+1, 5):
        qc.cp(angles[j-i-1], i, j)

# Add a final SWAP-reversal layer to swap qubit i with qubit 4-i for i=0..1
for i in range(2):
    qc.swap(i, 4-i)

